import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("MHPCO Claim Office — quote", () => {
  // Edge case: empty
  it("empty item list → premium 5 G (only the processing fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [], 0).premium).toBe(5);
  });

  // Price list (base premiums), newcomer flags off, plus fee
  it("single sword (0 years, first contract) → 100 base +10% first insurance +5 fee = 115 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0).premium).toBe(115);
  });
  it.todo("single amulet → 60 base +10% first insurance + 5 fee = 71 G");
  it.todo("single staff → 80 base +10% + 5 fee = 93 G");
  it.todo("single potion → 40 base +10% + 5 fee = 49 G");

  // Components and building blocks
  it.todo("2 runes → base premium 50 G (55 + 5 = 60 G)");
  it.todo("3 runes → block base premium 60 G (66 + 5 = 71 G)");
  it.todo("4 runes → base premium 100 G, no block (110 + 5 = 115 G)");
  it.todo("7 runes → base premium 175 G (192.5 → rounded up 193 + 5 = 198 G)");
  it.todo("2 runes + 1 moonstone → base premium 75 G, no block for different types (82.5 → 83 + 5 = 88 G)");
  it.todo("3 runes + 3 moonstones → base premium 120 G, two separate blocks (132 + 5 = 137 G)");

  // Item-specific modifiers
  it.todo("newcomer cursed steel sword enchantment 3 → 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (100 + 30 + 13 first = 143 + 5 = 148 G)");
  it.todo("cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30 = 180 + 18 first + 5 fee = 203 G)");
  it.todo("sword with enchantment 4, not cursed → no surcharge (115 G)");
  it.todo("cursed sword with enchantment 4 → only curse surcharge (165 G)");
  it.todo("cursed sword + plain amulet → cursed surcharge only on the sword: 210 base → +10% first = 231 + 5 = 236 G");

  // Policy-wide modifiers
  it.todo("customer with exactly 2 years → loyalty discount applies (sword: 100 − 20 + 10 = 90 + 5 = 95 G)");
  it.todo("customer with 1 year → no loyalty discount (sword 115 G)");
  it.todo("second contract → 15% follow-up discount and first insurance still applies (sword, 0 years: 100 + 10 − 15 = 95 + 5 = 100 G)");
  it.todo("long-standing customer's second contract with cursed sword enchantment 7 → 160 G");

  // Rounding
  it.todo("premium yielding 197.5 G → rounded up to 198 G (7 runes, 0 years, first contract)");

  // Insurance sum / cap
  it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("policy with sword and amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
  it.todo("sword and 3 runes → insurance sum 1750 G; block discount does not affect insurance sum");

  // Errors
  it.todo("unknown item type (broomstick) → throws an error");
});

describe("MHPCO Claim Office — claim", () => {
  it.todo("regular steel sword enchantment 3, damage 500 → payout 400 G");
  it.todo("rune damage 200 → payout 100 G (no special clause for components)");
  it.todo("steel sword enchantment 9, damage 1000 → payout 400 G (50% then deductible)");
  it.todo("dragon sword enchantment 5, damage 800 → payout 700 G (full reimbursement then deductible)");
  it.todo("dragon sword enchantment 9, damage 1000 → payout 400 G (50% rule wins)");
  it.todo("dragon sword with exactly enchantment 8, damage 1000 → payout 400 G");
  it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G (deductible once per damaged item)");
  it.todo("two swords insured, two sword damage entries → each has its own deductible");
  it.todo("payout yielding 350.5 G → rounded down to 350 G (enchantment 9 sword, damage 901)");
  it.todo("first claim of 1500 on a sword → payout 1400 G, remainingCap 600 G");
  it.todo("second claim of 1500 on the same sword → payout 600 G, remainingCap 0 G");
  it.todo("more sword damage entries than swords insured → throws an error");
  it.todo("damage to an item not in the policy (amulet when only sword insured) → throws an error");
  it.todo("damage to an item with unknown type → throws an error");
  it.todo("damage entry with negative amount → throws an error");
});

describe("MHPCO Claim Office — CLI", () => {
  it.todo("reads scenario JSON from stdin and writes results (quote then claim) to stdout");
  it.todo("unknown item type in quote → exits non-zero, writes error to stderr, no results on stdout");
  it.todo("claim with damage entry not covered by the policy → exits non-zero with error on stderr");
});

